export const DoctorConsultationModal = () => {
  const { toggleModal, selectedDoctor } = useAppContext();
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [messages, setMessages] = useState<{sender: 'me' | 'doc', text: string}[]>([
    { sender: 'doc', text: `Здравствуйте! Я ${selectedDoctor?.name || 'Врач'}. Чем могу помочь?` }
  ]);
  const [input, setInput] = useState('');

  const handleSend = () => {
    if (!input.trim()) return;
    setMessages(prev => [...prev, { sender: 'me', text: input }]);
    setInput('');
    // Mock doctor response
    setTimeout(() => {
      setMessages(prev => [...prev, { sender: 'doc', text: 'Понял вас. Опишите подробнее симптомы?' }]);
