          </div>

          <div className="flex-1 overflow-y-auto space-y-4">
             {bookings.length > 0 ? bookings.map(b => (
                <div key={b.id} className="border border-gray-100 bg-white rounded-2xl p-4 shadow-sm relative overflow-hidden">
                   <div className={`absolute left-0 top-0 bottom-0 w-1 ${b.status === 'confirmed' ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                   <div className="flex justify-between items-start mb-2 pl-2">
