                   </div>

                   <div className="flex gap-4 mb-3 pl-2">
                      <div className="flex items-center text-sm text-gray-700">
                         <CalendarDays size={14} className="mr-2 text-gray-400" /> 
                         <span className="font-bold">{b.date}</span>
                      </div>
                      <div className="flex items-center text-sm text-gray-700">
                         <Clock size={14} className="mr-2 text-gray-400" /> 
                         <span className="font-bold">{b.time}</span>
                      </div>
                   </div>

                   <div className="flex items-center justify-between pl-2 border-t border-gray-50 pt-3">
                      <div className="flex items-center">
                         <User size={14} className="mr-2 text-gray-400"/>
                         <span className="text-xs font-bold text-gray-600">{b.childName}</span>
                      </div>
                      {b.status === 'confirmed' && (
                         <button 
                           onClick={() => handleCancel(b)}
                           className="text-xs font-bold text-red-500 hover:text-red-600 bg-red-50 px-3 py-1.5 rounded-lg"
