                        : 'bg-white text-gray-800 rounded-bl-none border border-gray-100'
                  }`}>
                     <p>{msg.text}</p>
                     <span className={`text-[9px] block text-right mt-1 opacity-70 ${msg.senderId === 'me' ? 'text-indigo-100' : 'text-gray-400'}`}>
