type Language = 'ru' | 'uz';

interface UIState {
  isChatOpen: boolean;
  activeModal: 'none' | 'scan' | 'bookings' | 'wallet' | 'notifications' | 'doctor_consultation' | 'add_review' | 'booking_create' | 'child_profile' | 'cart' | 'product_details' | 'chat_list' | 'chat_room' | 'payment';
  chatTriggerMsg: string;
