  if (!paymentConfig) return null;

  const handlePay = async () => {
    setStatus('processing');
    setErrorMsg('');

    try {
      const result = await processPayment(method);
      if (result.success) {
        setStatus('success');
        setTimeout(() => {
          paymentConfig.onSuccess();
